/**
 * Every spelling a data row may use for a province, upper-cased for
 * matching: the Thai name, the English name with and without spaces
 * ("Chiang Mai", "CHIANGMAI"), and the slug ("chiangMai"). MapBlock keys
 * rows on these; lib/intelligence/autoCurf's region detector uses the same
 * set so a column it calls a province is one the map will actually place.
 */
export function thailandProvinceAliases(slug: string): string[] {
  const n = THAILAND_PROVINCE_NAMES[slug];
  const en = (n?.en ?? slug).toUpperCase();
  return [...new Set([n?.th ?? slug, en, en.replace(/\s+/g, ""), slug.toUpperCase()])];
}

/** Upper-cased alias → slug, for "is this value a Thai province?" checks. */
export const THAILAND_PROVINCE_BY_ALIAS: Record<string, string> = Object.fromEntries(
  Object.keys(THAILAND_PROVINCE_NAMES).flatMap((slug) => thailandProvinceAliases(slug).map((a) => [a, slug])),
);
